CREATE OR REPLACE FUNCTION public.app_admin_update_opportunity_status(p_opportunity_id uuid, p_status text, p_is_featured boolean, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_opportunity_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    UPDATE app.opportunities
    SET
        status = COALESCE(NULLIF(TRIM(COALESCE(p_status, status)), ''), status),
        is_featured = COALESCE(p_is_featured, is_featured),
        is_active = COALESCE(p_is_active, is_active),
        updated_at = NOW()
    WHERE id = p_opportunity_id
    RETURNING id INTO v_opportunity_id;

    IF v_opportunity_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'opportunity_id', v_opportunity_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_upsert_opportunity(p_opportunity_id uuid, p_title text, p_short_description text, p_description text, p_type text, p_category text, p_organization_name text, p_organization_logo_url text, p_country text, p_city text, p_is_remote_possible boolean, p_contract_type text, p_duration_months integer, p_start_date date, p_application_deadline date, p_status text, p_is_featured boolean, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_opportunity_id UUID;
    v_title TEXT := NULLIF(TRIM(COALESCE(p_title, '')), '');
    v_short_desc TEXT := NULLIF(TRIM(COALESCE(p_short_description, '')), '');
    v_type TEXT := NULLIF(TRIM(COALESCE(p_type, '')), '');
    v_org_name TEXT := NULLIF(TRIM(COALESCE(p_organization_name, '')), '');
    v_country TEXT := NULLIF(TRIM(COALESCE(p_country, '')), '');
    v_city TEXT := NULLIF(TRIM(COALESCE(p_city, '')), '');
    v_status TEXT := COALESCE(NULLIF(TRIM(COALESCE(p_status, '')), ''), 'draft');
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF v_title IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_title');
    END IF;

    IF v_short_desc IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_short_description');
    END IF;

    IF v_type IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_type');
    END IF;

    IF v_org_name IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_organization_name');
    END IF;

    IF v_country IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_country');
    END IF;

    IF v_city IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_city');
    END IF;

    IF p_opportunity_id IS NULL THEN
        INSERT INTO app.opportunities (
            title,
            short_description,
            description,
            type,
            category,
            organization_name,
            organization_logo_url,
            country,
            city,
            is_remote_possible,
            contract_type,
            duration_months,
            start_date,
            application_deadline,
            status,
            is_featured,
            is_active,
            created_by_user_id
        )
        VALUES (
            v_title,
            v_short_desc,
            p_description,
            v_type,
            p_category,
            v_org_name,
            p_organization_logo_url,
            v_country,
            v_city,
            COALESCE(p_is_remote_possible, FALSE),
            p_contract_type,
            p_duration_months,
            p_start_date,
            p_application_deadline,
            v_status,
            COALESCE(p_is_featured, FALSE),
            COALESCE(p_is_active, TRUE),
            v_user_id
        )
        RETURNING id INTO v_opportunity_id;
    ELSE
        UPDATE app.opportunities
        SET
            title = v_title,
            short_description = v_short_desc,
            description = p_description,
            type = v_type,
            category = p_category,
            organization_name = v_org_name,
            organization_logo_url = p_organization_logo_url,
            country = v_country,
            city = v_city,
            is_remote_possible = COALESCE(p_is_remote_possible, is_remote_possible),
            contract_type = p_contract_type,
            duration_months = p_duration_months,
            start_date = p_start_date,
            application_deadline = p_application_deadline,
            status = v_status,
            is_featured = COALESCE(p_is_featured, is_featured),
            is_active = COALESCE(p_is_active, is_active),
            updated_at = NOW()
        WHERE id = p_opportunity_id
        RETURNING id INTO v_opportunity_id;
    END IF;

    IF v_opportunity_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'opportunity_id', v_opportunity_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_upsert_opportunity_type(p_type_id uuid, p_code text, p_label text, p_sort_order integer, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_type_id UUID;
    v_code TEXT := NULLIF(TRIM(COALESCE(p_code, '')), '');
    v_label TEXT := NULLIF(TRIM(COALESCE(p_label, '')), '');
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF v_code IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_code');
    END IF;

    IF v_label IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_label');
    END IF;

    IF p_type_id IS NULL THEN
        INSERT INTO app.opportunity_types (
            code,
            label,
            sort_order,
            is_active
        )
        VALUES (
            v_code,
            v_label,
            COALESCE(p_sort_order, 0),
            COALESCE(p_is_active, TRUE)
        )
        RETURNING id INTO v_type_id;
    ELSE
        UPDATE app.opportunity_types
        SET
            code = v_code,
            label = v_label,
            sort_order = COALESCE(p_sort_order, sort_order),
            is_active = COALESCE(p_is_active, is_active),
            updated_at = NOW()
        WHERE id = p_type_id
        RETURNING id INTO v_type_id;
    END IF;

    IF v_type_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'type_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'type_id', v_type_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_opportunity_add_comment(p_opportunity_id uuid, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_comment_id UUID;
    v_new_count INTEGER;
    v_content TEXT := TRIM(COALESCE(p_content, ''));
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    IF v_content = '' OR LENGTH(v_content) < 2 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'content_too_short');
    END IF;

    IF LENGTH(v_content) > 1000 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'content_too_long');
    END IF;

    -- Vérifier si l'opportunité existe et est active
    IF NOT EXISTS (
        SELECT 1 FROM app.opportunities 
        WHERE id = p_opportunity_id AND is_active = TRUE AND status = 'published'
    ) THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_found');
    END IF;

    -- Insérer le commentaire
    INSERT INTO app.opportunity_comments (opportunity_id, user_id, content)
    VALUES (p_opportunity_id, v_user_id, v_content)
    RETURNING id INTO v_comment_id;

    -- Incrémenter le compteur
    UPDATE app.opportunities 
    SET comments_count = comments_count + 1, updated_at = NOW()
    WHERE id = p_opportunity_id
    RETURNING comments_count INTO v_new_count;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'comment_id', v_comment_id,
        'comments_count', v_new_count
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_opportunity_count_new()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_last_viewed TIMESTAMPTZ;
    v_count INTEGER;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', TRUE, 'count', 0);
    END IF;

    -- Récupérer la dernière date de consultation
    SELECT last_viewed_at INTO v_last_viewed
    FROM app.opportunity_views
    WHERE user_id = v_user_id;

    -- Si jamais consulté, compter toutes les opportunités des 7 derniers jours
    IF v_last_viewed IS NULL THEN
        v_last_viewed := NOW() - INTERVAL '7 days';
    END IF;

    -- Compter les nouvelles opportunités publiées depuis
    SELECT COUNT(*) INTO v_count
    FROM app.opportunities
    WHERE is_active = TRUE
      AND status = 'published'
      AND created_at > v_last_viewed
      AND (application_deadline IS NULL OR application_deadline >= CURRENT_DATE);

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'count', COALESCE(v_count, 0),
        'last_viewed_at', v_last_viewed
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_opportunity_delete_comment(p_comment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_opportunity_id UUID;
    v_owner_id UUID;
    v_new_count INTEGER;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    -- Vérifier ownership
    SELECT opportunity_id, user_id INTO v_opportunity_id, v_owner_id
    FROM app.opportunity_comments
    WHERE id = p_comment_id;

    IF v_opportunity_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'comment_not_found');
    END IF;

    IF v_owner_id != v_user_id THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_owner');
    END IF;

    -- Supprimer
    DELETE FROM app.opportunity_comments WHERE id = p_comment_id;

    -- Décrémenter le compteur
    UPDATE app.opportunities 
    SET comments_count = GREATEST(0, comments_count - 1), updated_at = NOW()
    WHERE id = v_opportunity_id
    RETURNING comments_count INTO v_new_count;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'comments_count', v_new_count
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_opportunity_get_my_reaction(p_opportunity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_reaction_type TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', TRUE, 'my_reaction', NULL);
    END IF;

    SELECT reaction_type INTO v_reaction_type
    FROM app.opportunity_reactions
    WHERE opportunity_id = p_opportunity_id AND user_id = v_user_id;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'my_reaction', v_reaction_type);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_opportunity_mark_viewed()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    -- Upsert la date de dernière consultation
    INSERT INTO app.opportunity_views (user_id, last_viewed_at)
    VALUES (v_user_id, NOW())
    ON CONFLICT (user_id) DO UPDATE
    SET last_viewed_at = NOW();

    RETURN JSONB_BUILD_OBJECT('success', TRUE);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_opportunity_toggle_reaction(p_opportunity_id uuid, p_reaction_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_existing_type TEXT;
    v_new_count INTEGER;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    IF p_reaction_type NOT IN ('like', 'love') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_reaction_type');
    END IF;

    -- Vérifier si l'opportunité existe et est active
    IF NOT EXISTS (
        SELECT 1 FROM app.opportunities 
        WHERE id = p_opportunity_id AND is_active = TRUE AND status = 'published'
    ) THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_found');
    END IF;

    -- Vérifier si une réaction existe déjà
    SELECT reaction_type INTO v_existing_type
    FROM app.opportunity_reactions
    WHERE opportunity_id = p_opportunity_id AND user_id = v_user_id;

    IF v_existing_type IS NOT NULL THEN
        IF v_existing_type = p_reaction_type THEN
            -- Même type: supprimer la réaction (toggle off)
            DELETE FROM app.opportunity_reactions
            WHERE opportunity_id = p_opportunity_id AND user_id = v_user_id;

            -- Décrémenter le compteur
            UPDATE app.opportunities 
            SET reactions_count = GREATEST(0, reactions_count - 1), updated_at = NOW()
            WHERE id = p_opportunity_id
            RETURNING reactions_count INTO v_new_count;

            RETURN JSONB_BUILD_OBJECT(
                'success', TRUE, 
                'action', 'removed',
                'my_reaction', NULL,
                'reactions_count', v_new_count
            );
        ELSE
            -- Type différent: mettre à jour
            UPDATE app.opportunity_reactions
            SET reaction_type = p_reaction_type
            WHERE opportunity_id = p_opportunity_id AND user_id = v_user_id;

            SELECT reactions_count INTO v_new_count
            FROM app.opportunities WHERE id = p_opportunity_id;

            RETURN JSONB_BUILD_OBJECT(
                'success', TRUE, 
                'action', 'updated',
                'my_reaction', p_reaction_type,
                'reactions_count', v_new_count
            );
        END IF;
    ELSE
        -- Pas de réaction: en créer une
        INSERT INTO app.opportunity_reactions (opportunity_id, user_id, reaction_type)
        VALUES (p_opportunity_id, v_user_id, p_reaction_type);

        -- Incrémenter le compteur
        UPDATE app.opportunities 
        SET reactions_count = reactions_count + 1, updated_at = NOW()
        WHERE id = p_opportunity_id
        RETURNING reactions_count INTO v_new_count;

        RETURN JSONB_BUILD_OBJECT(
            'success', TRUE, 
            'action', 'added',
            'my_reaction', p_reaction_type,
            'reactions_count', v_new_count
        );
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_apply_for_opportunity(p_opportunity_id uuid, p_message text, p_cv_url text, p_extra_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_opportunity_exists BOOLEAN;
    v_application_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'student' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_student');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.opportunities o
        WHERE o.id = p_opportunity_id
          AND o.is_active = TRUE
          AND o.status = 'published'
          AND (o.application_deadline IS NULL OR o.application_deadline >= CURRENT_DATE)
    ) INTO v_opportunity_exists;

    IF NOT v_opportunity_exists THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'opportunity_not_available');
    END IF;

    SELECT id
    INTO v_application_id
    FROM app.opportunity_applications a
    WHERE a.opportunity_id = p_opportunity_id
      AND a.student_id = v_user_id
    LIMIT 1;

    IF v_application_id IS NOT NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'already_applied');
    END IF;

    INSERT INTO app.opportunity_applications (
        opportunity_id,
        student_id,
        message,
        cv_url,
        extra_data,
        status
    )
    VALUES (
        p_opportunity_id,
        v_user_id,
        p_message,
        p_cv_url,
        p_extra_data,
        'submitted'
    )
    RETURNING id INTO v_application_id;

    IF v_application_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'application_failed');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'application_id', v_application_id);
END;
$function$
